<script setup lang="ts">
import {computed,ref,onUnmounted,watch} from 'vue'
import {onShow,onHide,onPullDownRefresh,onBackPress} from '@dcloudio/uni-app'
import AppIcon from '../../components/AppIcon.vue'
import {useCampus} from '../../stores/campus'
import {useDaylight} from '../../composables/useDaylight'
import {topInset} from '../../utils/layout'
import {clock,minute,seatProblem,type LibrarySeat} from '../../data/library'
type Area={id:string,name:string,total:number}
type Floor={id:string,name:string,total:number,areas:Area[]}
const campus=useCampus(),light=useDaylight(),statusHeight=uni.getSystemInfoSync().statusBarHeight||0
const mode=ref<'seats'|'mine'>('seats'),floors=ref<Floor[]>([]),floorId=ref(''),roomId=ref(''),date=ref(''),today=ref(''),tomorrow=ref('')
const seats=ref<LibrarySeat[]>([]),start=ref(''),end=ref(''),query=ref(''),onlyAvailable=ref(false),now=ref(Date.now()),serverOffset=ref(0)
const loading=ref(false),catalogLoading=ref(false),error=ref(''),mineError=ref(''),mine=ref<any[]>([]),mineLoading=ref(false),pending=ref<any[]>([])
const selected=ref<LibrarySeat|null>(null),sheet=ref(false),captchaRequired=ref(true),captchaImage=ref(''),captcha=ref(''),captchaLoading=ref(false),captchaError=ref(''),captchaLoadedAt=ref(0)
const submitting=ref(false),result=ref<any>(null),requestId=ref(''),submitError=ref('')
const timeSheet=ref<'start'|'end'|null>(null)
let initialized=false,loadGeneration=0,mineGeneration=0,captchaGeneration=0,timer:ReturnType<typeof setInterval>|undefined
const floor=computed(()=>floors.value.find(f=>f.id===floorId.value)),areas=computed(()=>floor.value?.areas||[]),area=computed(()=>areas.value.find(a=>a.id===roomId.value))
const ruleSeat=computed(()=>seats.value.find(s=>s.bookable&&s.open_times.length)),rule=computed(()=>ruleSeat.value?.rules)
const startChoices=computed(()=>{const s=ruleSeat.value;if(!s||!date.value)return [];const out=new Set<string>(),step=Math.max(1,s.rules.step_minutes);for(const w of s.open_times)for(let m=Math.ceil(minute(w.start)/step)*step;m+s.rules.min_minutes<=minute(w.end);m+=step){const t=clock(m);if(Date.parse(`${date.value}T${t}:00+08:00`)>now.value)out.add(t)}return [...out].sort()})
const endChoices=computed(()=>{const s=ruleSeat.value;if(!s||!start.value)return [];const a=minute(start.value),step=Math.max(1,s.rules.step_minutes),out=new Set<string>();for(const w of s.open_times){if(a<minute(w.start)||a>=minute(w.end))continue;for(let m=a+s.rules.min_minutes;m<=Math.min(a+s.rules.max_minutes,minute(w.end));m+=step)out.add(clock(m))}return [...out].sort()})
const duration=computed(()=>start.value&&end.value?minute(end.value)-minute(start.value):0)
const seatStates=computed(()=>new Map(seats.value.map(s=>{const reason=seatProblem(s,date.value,start.value,end.value,now.value);return [s.id,!reason?'available':reason==='所选时段已被预约'?'occupied':'closed']})))
const stateLabels={available:'可约',occupied:'占用',closed:'未开放',picked:'已选'}
function seatState(seat:LibrarySeat){return seatStates.value.get(seat.id)||'closed'}
const available=computed(()=>seats.value.filter(s=>seatState(s)==='available').length)
const visibleSeats=computed(()=>seats.value.filter(s=>(!onlyAvailable.value||seatState(s)==='available')&&s.name.toLowerCase().includes(query.value.trim().toLowerCase())))
const problem=computed(()=>selected.value?seatProblem(selected.value,date.value,start.value,end.value,now.value):'请选择座位')
const dayLabel=computed(()=>date.value===today.value?'今天':'明天')
function timeLabel(ms:number){return new Date(ms+8*3600000).toISOString().slice(11,16)}
function toast(message:string){uni.showToast({title:message,icon:'none'})}
function back(){if(submitting.value){toast('正在处理预约，请稍候');return}uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/index/index'})})}
function resetTimes(){if(!startChoices.value.includes(start.value))start.value=startChoices.value[0]||'';if(!endChoices.value.includes(end.value))end.value=endChoices.value[0]||''}
async function loadArea(autoTomorrow=false){const id=++loadGeneration,room=roomId.value,day=date.value;seats.value=[];error.value='';loading.value=true;query.value='';try{const data=await campus.librarySeats(room,day);if(id!==loadGeneration)return;serverOffset.value=Date.parse(data.observed_at)-Date.now();now.value=Date.now()+serverOffset.value;seats.value=data.seats;resetTimes();if(autoTomorrow&&!start.value&&date.value===today.value){date.value=tomorrow.value;await loadArea()}}catch(e){if(id===loadGeneration)error.value=(e as Error).message}finally{if(id===loadGeneration)loading.value=false}}
async function loadMine(){const id=++mineGeneration;mineLoading.value=true;mineError.value='';try{const data=await campus.libraryReservations(date.value);if(id===mineGeneration)mine.value=data.items}catch(e){if(id===mineGeneration)mineError.value=(e as Error).message}finally{if(id===mineGeneration)mineLoading.value=false}}
async function loadPending(){try{pending.value=(await campus.libraryUnfinished()).items}catch{}}
async function initialize(){catalogLoading.value=true;error.value='';try{const c=await campus.libraryCatalog();floors.value=c.floors;captchaRequired.value=c.captcha_required;today.value=c.today;tomorrow.value=c.tomorrow;date.value=date.value===c.tomorrow?c.tomorrow:c.today;floorId.value=floors.value[0]?.id||'';roomId.value=areas.value[0]?.id||'';initialized=true;if(roomId.value)await loadArea(true);void loadPending()}catch(e){error.value=(e as Error).message}finally{catalogLoading.value=false}}
function selectFloor(id:string){if(submitting.value||floorId.value===id)return;floorId.value=id;roomId.value=areas.value[0]?.id||'';selected.value=null;void loadArea()}
function selectArea(id:string){if(submitting.value||roomId.value===id)return;roomId.value=id;selected.value=null;void loadArea()}
function selectDate(value:string){if(submitting.value||value===date.value)return;date.value=value;selected.value=null;if(mode.value==='mine')void loadMine();else void loadArea()}
function selectTime(value:string){if(timeSheet.value==='start'){start.value=value;if(!endChoices.value.includes(end.value))end.value=endChoices.value[0]||''}else end.value=value;timeSheet.value=null;selected.value=null}
function quickDuration(minutes:number){const choice=clock(minute(start.value)+minutes);if(endChoices.value.includes(choice))end.value=choice}
async function showCaptcha(){if(!captchaRequired.value||captchaLoading.value)return;const generation=++captchaGeneration;captchaLoading.value=true;captchaError.value='';captcha.value='';captchaImage.value='';try{const c=await campus.libraryCaptcha();if(generation!==captchaGeneration)return;captchaImage.value=c.image;captchaLoadedAt.value=Date.now()}catch(e){if(generation===captchaGeneration)captchaError.value=(e as Error).message}finally{if(generation===captchaGeneration)captchaLoading.value=false}}
function chooseSeat(seat:LibrarySeat){if(submitting.value)return;selected.value=seat;sheet.value=true;result.value=null;requestId.value='';submitError.value='';captcha.value='';captchaImage.value='';if(!problem.value)void showCaptcha()}
function closeSheet(){if(submitting.value)return;sheet.value=false;selected.value=null;captchaGeneration++;captchaLoading.value=false;captcha.value='';captchaImage.value=''}
function newId(){return Date.now().toString(16).padStart(12,'0')+Array.from({length:20},()=>Math.floor(Math.random()*16).toString(16)).join('')}
async function consume(response:any){result.value=response;requestId.value=response.request_id||requestId.value;if(response.status==='verified'){captcha.value='';captchaImage.value='';void loadPending();void loadMine()}else if(response.status==='rejected'){requestId.value='';if(selected.value&&!problem.value)await showCaptcha()}else void loadPending()}
async function submit(){if(submitting.value||!selected.value||result.value?.status==='uncertain'||result.value?.status==='verified')return;if(problem.value){submitError.value=problem.value;return}if(captchaRequired.value&&(!captcha.value.trim()||!captchaImage.value)){submitError.value='请输入图片中的验证码';return}if(captchaRequired.value&&Date.now()-captchaLoadedAt.value>110000){submitError.value='验证码已过期，请重新输入';await showCaptcha();return}submitting.value=true;submitError.value='';requestId.value=requestId.value||newId();try{await consume(await campus.libraryBook({request_id:requestId.value,room_id:roomId.value,seat_id:selected.value.id,date:date.value,start:start.value,end:end.value,captcha:captcha.value.trim()}))}catch(e){if([400,401,403,409,422,429].includes((e as any).status)){result.value={status:'rejected',message:(e as Error).message};requestId.value=''}else{result.value={status:'uncertain',message:(e as Error).message+'。请先核实这次预约结果。'};void loadPending()}}finally{submitting.value=false}}
async function verify(id=requestId.value){if(submitting.value||!id)return;submitting.value=true;submitError.value='';try{await consume(await campus.libraryBookingStatus(id))}catch(e){submitError.value=(e as Error).message;result.value={status:'uncertain',message:'结果尚未核实，勿重复提交。请稍后刷新或查看我的预约。'}}finally{submitting.value=false}}
function verifyPending(item:any){selected.value=null;requestId.value=item.request_id;result.value={status:'uncertain',message:'正在核实此前的预约请求'};sheet.value=true;void verify(item.request_id)}
function showMine(){if(submitting.value)return;sheet.value=false;mode.value='mine';void loadMine()}
function showSeats(){mode.value='seats';if(initialized)void loadArea()}
function openSchedule(){if(submitting.value)return;uni.navigateTo({url:'/pages/schedule/index?date='+date.value})}
async function refresh(){if(submitting.value){uni.stopPullDownRefresh();return}if(!initialized)await initialize();else if(mode.value==='mine')await loadMine();else await loadArea();void loadPending();uni.stopPullDownRefresh()}
function status(){
 // #ifdef H5
 const color=light.dark.value?'#121e34':'#f1f7fd';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',color);document.body.style.backgroundColor=color;document.documentElement.style.backgroundColor=color
 // #endif
 // #ifdef APP-PLUS
 const p=(globalThis as any).plus;p?.navigator?.setStatusBarStyle(light.dark.value?'light':'dark')
 // #endif
}
watch(()=>light.period.value.id,status)
function tick(){now.value=Date.now()+serverOffset.value;if(initialized&&today.value!==new Date(now.value+8*3600000).toISOString().slice(0,10)&&!submitting.value){closeSheet();initialized=false;void initialize()}}
onShow(async()=>{campus.agendaVisible=false;status();clearInterval(timer);timer=setInterval(tick,30000);await campus.boot();if(!campus.authenticated){uni.reLaunch({url:'/pages/index/index'});return}if(initialized&&today.value!==new Date(Date.now()+serverOffset.value+8*3600000).toISOString().slice(0,10))initialized=false;if(!initialized)void initialize();else if(!submitting.value)void refresh()})
onHide(()=>{clearInterval(timer);captcha.value='';captchaLoadedAt.value=0})
onUnmounted(()=>clearInterval(timer))
onPullDownRefresh(refresh)
onBackPress(()=>{if(submitting.value){toast('正在处理预约，请稍候');return true}if(timeSheet.value){timeSheet.value=null;return true}if(sheet.value){closeSheet();return true}return false})
</script>

<template><view class="library-page" :class="['period-'+light.period.value.id,{night:light.dark.value}]">
 <view class="library-header" :style="{paddingTop:topInset(16,statusHeight)}"><view class="library-back" @click="back"><AppIcon name="back" :size="38"/></view><text>图书馆</text><view class="library-history" @click="openSchedule"><AppIcon name="calendar" :size="34"/></view></view>
 <view class="library-body"><view class="library-intro"><view><text>座位预约</text><text>选择时段，查看可预约座位</text></view><view class="library-book-icon"><AppIcon name="book" :size="56"/></view></view>
 <view class="library-tabs"><view :class="{active:mode==='seats'}" @click="showSeats">选座预约</view><view :class="{active:mode==='mine'}" @click="showMine">我的预约<text v-if="mine.length">{{mine.length}}</text></view></view>
 <view v-if="today" class="library-date-row"><view v-for="d in [{date:today,label:'今天'},{date:tomorrow,label:'明天'}]" :key="d.date" :class="{active:date===d.date}" @click="selectDate(d.date)"><text>{{d.label}}</text><text>{{d.date.slice(5).replace('-','月')}}日</text><AppIcon v-if="date===d.date" name="calendar-white" :size="29"/></view></view>
 <view v-for="p in pending" :key="p.request_id" class="library-pending" @click="verifyPending(p)"><view><text>有一笔预约结果待核实</text><text>{{p.booking.date}} · {{p.booking.start}}–{{p.booking.end}}</text></view><text>核实 ›</text></view>
 <template v-if="mode==='seats'">
  <view v-if="catalogLoading" class="library-empty library-panel"><view class="library-loading-dot"/><text>正在读取阅览区域…</text></view>
  <template v-else-if="floors.length"><view class="library-floor-row"><view v-for="f in floors" :key="f.id" :class="{active:floorId===f.id}" @click="selectFloor(f.id)">{{f.name.replace('图书馆','')}}</view></view>
   <view class="library-area-grid"><view v-for="a in areas" :key="a.id" :class="{active:roomId===a.id}" @click="selectArea(a.id)"><view><text>{{a.name.replace(floor?.name.replace('图书馆','')||'','')}}</text><text>{{a.total}} 个座位</text></view><text class="library-area-check">{{roomId===a.id?'✓':'›'}}</text></view></view>
   <view class="library-time-card library-panel"><view class="library-section-heading"><text>预约时段</text><text v-if="duration>0">{{duration/60}} 小时</text></view><view class="library-time-fields"><view @click="startChoices.length?timeSheet='start':toast('当天已无完整预约时段，请选择明天')"><text>开始</text><text>{{start||'无可选时间'}}</text><text>⌄</text></view><text class="library-time-arrow">→</text><view @click="endChoices.length?timeSheet='end':toast('请先选择开始时间')"><text>结束</text><text>{{end||'—'}}</text><text>⌄</text></view></view><view v-if="start" class="library-durations"><view v-for="n in [120,180,300].filter(n=>endChoices.includes(clock(minute(start)+n)))" :key="n" :class="{active:duration===n}" @click="quickDuration(n)">{{n/60}} 小时</view></view><text v-if="rule" class="library-rule-note">单次 {{rule.min_minutes/60}}–{{rule.max_minutes/60}} 小时 · {{rule.step_minutes}} 分钟对齐 · 每天最多 {{rule.daily_limit}} 笔</text><text v-if="!loading&&!start" class="library-notice">今天剩余开放时间不足，或本区域尚未开放。可切换明天查看。</text></view>
   <view class="library-seat-section library-panel"><view class="library-section-heading"><text>{{area?.name||'座位'}}</text><text>{{loading?'更新中…':available+' / '+seats.length+' 可约'}}</text></view><view class="library-search"><AppIcon name="search" :size="30"/><input v-model="query" maxlength="25" placeholder="搜索座位号，如 015"/><text v-if="query" @click="query=''">×</text></view><view class="library-seat-tools"><view class="library-legend"><view v-for="(label,state) in stateLabels" :key="state"><text :class="state">{{state==='occupied'?'×':state==='picked'?'✓':''}}</text><text>{{label}}</text></view></view><view class="library-filter" :class="{active:onlyAvailable}" @click="onlyAvailable=!onlyAvailable"><text>{{onlyAvailable?'✓':'○'}}</text>仅看可约</view></view>
    <view v-if="loading" class="library-seat-grid skeleton"><view v-for="i in 24" :key="i"/></view><view v-else-if="error" class="library-empty"><text>{{error}}</text><button @click="loadArea()">重新加载</button></view><view v-else-if="!visibleSeats.length" class="library-empty"><AppIcon name="search" :size="58"/><text>{{query?'没有找到这个座位号':onlyAvailable?'所选时段暂无可约座位':'该区域暂无座位'}}</text></view><view v-else class="library-seat-grid"><view v-for="s in visibleSeats" :key="s.id" :class="[seatState(s),{picked:selected?.id===s.id&&seatState(s)==='available'}]" :aria-label="s.name+'，'+stateLabels[seatState(s) as keyof typeof stateLabels]" role="button" @click="chooseSeat(s)"><view class="library-seat-shape"/><view v-if="seatState(s)==='closed'" class="library-seat-lock"/><text v-else-if="seatState(s)==='occupied'||selected?.id===s.id" class="library-seat-mark">{{seatState(s)==='occupied'?'×':'✓'}}</text><text>{{s.name}}</text></view></view>
   </view><text class="library-bottom-note">按座位号排列 · 颜色对应所选时段 · 提交时再次核对余位</text>
  </template><view v-else-if="error" class="library-empty library-panel"><text>{{error}}</text><button @click="initialize">重试</button></view>
 </template>
 <template v-else><view class="library-section-heading library-my-heading"><text>{{dayLabel}}的预约</text><text @click="loadMine">{{mineLoading?'刷新中…':'刷新 ↻'}}</text></view><view v-if="mineError" class="library-pending" @click="loadMine">{{mineError}} · 点击重试</view><view v-for="r in mine" :key="r.id" class="library-reservation library-panel"><view><text>{{r.seat}}</text><text class="library-status" :class="{done:r.usage_status_text==='已结束'}">{{r.usage_status_text}}</text></view><text>{{r.area}}</text><view class="library-reservation-time"><AppIcon name="calendar" :size="29"/><text>{{date}} · {{timeLabel(r.begin_ms)}}–{{timeLabel(r.end_ms)}}</text></view><text class="library-reservation-label">{{r.status_labels.join(' · ')}}</text></view><view v-if="!mine.length&&!mineLoading&&!mineError" class="library-empty library-panel"><AppIcon name="book" :size="72"/><text>{{dayLabel}}暂无本人预约</text><button @click="showSeats">去选座</button></view><text class="library-bottom-note" @click="openSchedule">查看完整日程与历史预约 ›</text></template>
 </view>
 <view v-if="sheet" class="library-mask" @click="closeSheet"><view class="library-sheet" @click.stop><view class="library-handle"/><view class="library-sheet-heading"><view><text>{{result?.status==='verified'?'预约已确认':selected?.name||'预约结果'}}</text><text v-if="selected">{{area?.name}}</text></view><text @click="closeSheet">×</text></view>
  <view v-if="selected" class="library-review"><view><text>日期</text><text>{{date}} · {{dayLabel}}</text></view><view><text>时段</text><text>{{start||'—'}}–{{end||'—'}} · {{duration/60}} 小时</text></view></view>
  <view v-if="result" class="library-result" :class="result.status"><AppIcon :name="result.status==='verified'?'calendar':'info'" :size="37"/><text>{{result.message}}</text></view>
  <template v-if="selected&&result?.status!=='verified'&&result?.status!=='uncertain'"><view v-if="problem" class="library-result rejected">{{problem}}，请关闭后调整时段。</view><template v-else><text class="library-sheet-note">本地模拟交互，不会提交真实预约。</text><view v-if="captchaRequired" class="library-captcha"><view><text>验证码</text><text @click="!submitting && showCaptcha()">{{captchaLoading?'加载中…':'换一张 ↻'}}</text></view><view><input v-model="captcha" maxlength="12" placeholder="输入右侧验证码" :disabled="submitting"/><image v-if="captchaImage" :src="captchaImage" mode="aspectFit" @click="!submitting && showCaptcha()"/><view v-else class="library-captcha-placeholder" @click="!submitting && showCaptcha()">{{captchaLoading?'加载中':'点击重试'}}</view></view><text v-if="captchaError">{{captchaError}}</text></view></template>
   <view v-if="selected.occupied.length" class="library-occupied-times"><text>这个座位已被预约的时段</text><view><text v-for="(r,i) in selected.occupied" :key="i">{{timeLabel(r.begin_ms)}}–{{timeLabel(r.end_ms)}}</text></view></view>
  </template><text v-if="submitError" class="library-submit-error">{{submitError}}</text>
  <button v-if="result?.status==='verified'" class="library-primary" @click="showMine">查看我的预约</button><button v-else-if="result?.status==='uncertain'" class="library-primary" :loading="submitting" :disabled="submitting" @click="verify()">核实预约结果</button><button v-else class="library-primary" :loading="submitting" :disabled="submitting||!!problem||captchaLoading" @click="submit">{{submitting?'正在提交并核实…':'模拟预约'}}</button><text class="library-sheet-foot">{{result?.status==='uncertain'?'请先核实本次结果，避免重复预约':'仅在本地内存中演示，不提交真实预约'}}</text>
 </view></view>
 <view v-if="timeSheet" class="library-mask" @click="timeSheet=null"><view class="library-sheet library-time-sheet" @click.stop><view class="library-handle"/><view class="library-sheet-heading"><text>选择{{timeSheet==='start'?'开始':'结束'}}时间</text><text @click="timeSheet=null">×</text></view><scroll-view scroll-y class="library-time-options"><view class="library-clock-grid"><view v-for="v in timeSheet==='start'?startChoices:endChoices" :key="v" :class="{active:v===(timeSheet==='start'?start:end)}" @click="selectTime(v)">{{v}}</view></view></scroll-view></view></view>
</view></template>

<style lang="scss">
.library-page{--bg:#f1f7fd;--panel:#fff;--ink:#18304f;--muted:#8b9bb1;--soft:#edf4fc;--line:#e8eff7;min-height:100vh;min-height:100dvh;background:var(--bg);color:var(--ink);padding-bottom:calc(30rpx + env(safe-area-inset-bottom));font-family:-apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif;padding-left:env(safe-area-inset-left,0px);padding-right:env(safe-area-inset-right,0px)}.library-page.night{--bg:#121e34;--panel:#1e2d46;--ink:#edf3ff;--muted:#9aaac4;--soft:#263650;--line:#30405a}.library-header{display:flex;align-items:center;justify-content:space-between;padding:0 30rpx 25rpx;font-size:31rpx;font-weight:650}.library-back,.library-history{min-width:44px;min-height:44px;display:flex;align-items:center;justify-content:center;border-radius:50%}.library-body{padding:0 28rpx;max-width:1000rpx;margin:auto}.library-intro{display:flex;justify-content:space-between;align-items:center;margin:17rpx 5rpx 28rpx}.library-intro text{display:block;font-size:35rpx;font-weight:700}.library-intro text+text{font-size:23rpx;font-weight:400;color:var(--muted);margin-top:10rpx}.library-book-icon{width:95rpx;height:95rpx;border-radius:29rpx;display:flex;align-items:center;justify-content:center;background:#3688ff16}.library-tabs{display:flex;padding:7rpx;background:var(--soft);border-radius:22rpx;margin-bottom:25rpx}.library-tabs>view{flex:1;text-align:center;font-size:26rpx;padding:20rpx 8rpx;color:var(--muted);border-radius:17rpx}.library-tabs .active{background:var(--panel);color:var(--ink);font-weight:600;box-shadow:0 4rpx 10rpx #215b8b06}.library-tabs text{margin-left:9rpx;color:#438df0;font-size:20rpx}.library-date-row{display:flex;gap:17rpx;margin-bottom:28rpx}.library-date-row>view{flex:1;display:flex;align-items:center;gap:14rpx;border-radius:20rpx;padding:22rpx;background:var(--panel);font-size:26rpx;border:2rpx solid transparent}.library-date-row>view>text+text{font-size:22rpx;opacity:.65}.library-date-row>view>.app-icon{margin-left:auto}.library-date-row .active{ba